mapper.sql:
WHERE w.work_type = #{type}
  AND 

  AND c.slug = #{query.category}




  AND (
    SELECT COUNT(*)
    FROM fl_work_tag wt
    JOIN fl_tag t ON t.id = wt.tag_id
    WHERE wt.work_id = w.id AND t.slug IN
    #{slug}
  ) = #{tagCount}


  AND (INSTR(LOWER(w.title), LOWER(#{query.keyword})) > 0
       OR INSTR(LOWER(w.summary), LOWER(#{query.keyword})) > 0)

mapper.select:
SELECT gp.work_id, p.id, p.slug, p.name FROM fl_game_platform gp JOIN fl_platform p ON p.id = gp.platform_id WHERE gp.work_id IN
#{workId}
ORDER BY gp.work_id, p.sort_order, p.id
